mapper.select:
select
    (select count(1) from pms_product where del_flag = '0') as productCount,
    (select ifnull(sum(qty),0) from pms_purchase

            AND status = '0'
            AND purchase_time >= #{beginTime}
            AND purchase_time <= #{endTime}
            AND supplier_id = #{supplierId}
            AND product_name like concat('%', #{productName}, '%')

    ) as purchaseQty,
    (select ifnull(sum(stock_qty),0) from pms_product where del_flag = '0') as stockQty,
    (select ifnull(sum(amount),0) from pms_purchase

            AND status = '0'
            AND purchase_time >= #{beginTime}
            AND purchase_time <= #{endTime}
            AND supplier_id = #{supplierId}
            AND product_name like concat('%', #{productName}, '%')

    ) as purchaseCost,
    (select count(1) from pms_product where del_flag = '0' and stock_qty > 0 and stock_qty < ifnull(#{warnThreshold},5)) as warnCount,
    (select count(1) from pms_product where del_flag = '0' and stock_qty <= 0) as emptyCount
from dual
